def run_a1(rel: Release) -> dict:
    clinical, protein = _clinical(rel), _protein(rel)
    er = clinical.set_index("sampleID")[ER]
    twice = set(er.index[er.index.duplicated()]) & {str(s) for s in protein.columns}
    if twice:                       # the reference script can't run either: each id must have one ER status
        raise ValueError(f"A1 cannot run: {len(twice)} protein sample(s) appear on more than one clinical row "
                         f"({', '.join(sorted(twice)[:3])})")
    samples = [s for s in protein.columns if sample_type(str(s)) == "01" and er.get(s) in ("Positive", "Negative")]
    if "ERALPHA" not in protein.index or not samples:
        raise ValueError("A1 cannot run: the ERALPHA row or the ER-labelled primary tumors are missing")
    if int((protein.index == "ERALPHA").sum()) > 1:
        raise ValueError("A1 cannot run: the protein file has more than one ERALPHA row")
    vals = protein.loc["ERALPHA", samples]
    groups = {k: vals[[s for s in samples if er[s] == k]] for k in ("Positive", "Negative")}
    empty = [k for k, g in groups.items() if int(g.count()) == 0]
    if empty:
        raise ValueError("A1 cannot run: no ER-alpha value for the ER-" + " or ER-".join(k.lower() for k in empty)
                         + " primary tumors")

def assess(card: dict, release: Release, cmp: Comparison | None = None, results: dict | None = None,
           allow_missing: bool = False) -> dict:
    issues = run_checks(release, card, allow_missing=allow_missing)
    touching = changes_touching(card, cmp) if cmp else []
    robust = {}
    if "A1" in (card.get("analyses") or []):
        try:
            robust = conclusion(cmp if cmp else release, sorted({s for t in touching for s in t["samples"]}))
        except Exception:  # the robustness readout must never break the verdict
            robust = {}
        if robust:
            issues.append(_conclusion_issue(robust, bool(cmp)))
    material = [x for x in issues if x.material]
    eb = {}
    if set(card.get("analyses") or []) & {"A1", "A2"} and release.has("clinical.tsv"):
        try:                                     # the error budget is context; it must never break the verdict
            clin = _clinical(release)
            f1 = (a1_frames(clin, _protein(release)) if "A1" in card["analyses"] and release.has("protein_rppa.tsv.gz")
                  else None)
            c2 = (clin[clin.sampleID.str[13:15] == "01"].dropna(subset=[PAM50])[PAM50].value_counts().to_dict()
                  if "A2" in card["analyses"] else None)
            eb = error_budget(card, f1, c2, cmp, touching, clin.set_index("sampleID")[ER].to_dict() if cmp else {})
        except Exception:
            eb = {}

